/* Inflates the syllable table to MW_KFONT_ADDR and verifies it. Returns 1 if every byte is where it belongs, 0 if
 * the table failed to decode or its checksum is wrong (a build bug; the caller reports it). Must run before
 * anything draws a Hangul glyph -- kernel_boot() does it right after the serial port is up. */
static int ko_font_init(void) {
    u8 *dst = (u8 *)(MW_KFONT_ADDR);
    if (lz4_block_decode(font_ko_packed, KO_FONT_PACKED_BYTES, dst, KO_FONT_RAW_BYTES) != KO_FONT_RAW_BYTES) return 0;
    u32 h = 0x811C9DC5u;
    for (u32 i = 0; i < KO_FONT_RAW_BYTES; i++) h = (h ^ dst[i]) * 0x01000193u;
    return h == KO_FONT_CHECKSUM;
}

